H = {
 "nav.toy": ("Bomba de juguete", "Legetøjsvarmepumpe"),
 "about.toy": ('La <a href="toy.html">bomba de calor de juguete</a> te deja armar una con piezas y hacerla funcionar entre dos baldes de agua, con una lista de compras para construir una de verdad.',
               '<a href="toy.html">Legetøjsvarmepumpen</a> lader dig bygge en af dele og køre den mellem to spande vand, med en indkøbsliste til at bygge en rigtig.'),
 "ln.toy": ('¿Quieres verla funcionar? <a href="toy.html">Arma una bomba de calor de juguete</a> con un compresor, una válvula y dos serpentines, hazla funcionar entre dos baldes de agua y encuentra las piezas para construir una de verdad.',
            'Vil du se den virke? <a href="toy.html">Byg en legetøjsvarmepumpe</a> af en kompressor, en ventil og to spiraler, kør den mellem to spande vand, og find delene til at bygge en rigtig.'),
 "ty.title": ("Arma una bomba de calor de juguete — Heat Pump Studio", "Byg en legetøjsvarmepumpe — Heat Pump Studio"),
 "ty.meta": ("Arma una bomba de calor de juguete con un compresor, una válvula y dos serpentines, y hazla funcionar entre dos baldes de agua: uno se calienta y el otro se congela. Además, experimentos seguros para hacer en casa.",
             "Byg en legetøjsvarmepumpe af en kompressor, en ventil og to spiraler, og kør den mellem to spande vand: den ene bliver varm, den anden fryser. Plus sikre forsøg, du kan lave derhjemme."),
 "ty.sub": ("bomba de calor de juguete", "legetøjsvarmepumpe"),
 "ty.h1": ("Arma una bomba de calor de juguete", "Byg en legetøjsvarmepumpe"),
 "ty.intro": ("Dos baldes de agua, un compresor pequeño como el de un refrigerador, una válvula de expansión y dos serpentines de cobre. Pon las piezas en su lugar y enciéndela: un balde se calienta mientras el otro se enfría, hasta que empieza a congelarse. Después cambia las piezas y mira qué pasa.",
              "To spande vand, en lille kompressor som den i et køleskab, en ekspansionsventil og to kobberspiraler. Sæt delene de rigtige steder, og tænd: den ene spand bliver varm, mens den anden bliver koldere, til den begynder at fryse. Skift så delene ud, og se, hvad der sker."),
 "ty.h.build": ("1. Ármala", "1. Byg den"),
 "ty.how": ("Arrastra una pieza a uno de los cuatro lugares punteados, o toca una pieza y luego un lugar. Toca una pieza puesta para devolverla. El refrigerante circula en el sentido de las agujas del reloj, como indican las flechas.",
            "Træk en del hen på en af de fire stiplede pladser, eller tryk på en del og derefter en plads. Tryk på en placeret del for at tage den tilbage. Kølemidlet løber med uret, i pilenes retning."),
 "ty.rigT": ("La bomba de calor de juguete: dos baldes, dos tubos y cuatro lugares para piezas", "Legetøjsvarmepumpen: to spande, to rør og fire pladser til dele"),
 "ty.bucketL": ("balde izquierdo", "venstre spand"),
 "ty.bucketR": ("balde derecho", "højre spand"),
 "ty.h.parts": ("Caja de piezas", "Kasse med dele"),
 "ty.show": ("Muéstrame", "Vis mig"),
 "ty.clear": ("Vaciar el montaje", "Tøm opstillingen"),
 "ty.h.run": ("2. Hazla funcionar", "2. Kør den"),
 "ty.f.comp": ("Compresor", "Kompressor"),
 "ty.c40": ("pequeño, 40 W", "lille, 40 W"),
 "ty.c80": ("mediano, 80 W (un refrigerador)", "mellem, 80 W (et køleskab)"),
 "ty.c120": ("grande, 120 W", "stor, 120 W"),
 "ty.f.fluid": ("Refrigerante", "Kølemiddel"),
 "ty.r134a": ("R134a (refrigeradores antiguos)", "R134a (ældre køleskabe)"),
 "ty.r290": ("R290, propano (refrigeradores nuevos)", "R290, propan (nye køleskabe)"),
 "ty.f.size": ("Cada balde contiene", "Hver spand rummer"),
 "ty.f.start": ("Agua al comienzo", "Vand ved start"),
 "ty.f.ins": ("Baldes", "Spande"),
 "ty.open": ("baldes de plástico abiertos", "åbne plastspande"),
 "ty.foam": ("en cajas de plumavit", "i flamingokasser"),
 "ty.f.speed": ("Velocidad", "Hastighed"),
 "ty.s60": ("1 s = 1 minuto", "1 s = 1 minut"),
 "ty.s300": ("1 s = 5 minutos", "1 s = 5 minutter"),
 "ty.s1200": ("1 s = 20 minutos", "1 s = 20 minutter"),
 "ty.run": ("Encender", "Tænd"),
 "ty.reset": ("Empezar de nuevo", "Start forfra"),
 "ty.ch1": ("Temperaturas del agua, °C", "Vandtemperaturer, °C"),
 "ty.ch2": ("COP: calor entregado ÷ electricidad usada", "COP: leveret varme ÷ brugt strøm"),
 "ty.h.try": ("3. Experimentos para probar", "3. Forsøg, du kan prøve"),
 "ty.try1": ("<b>Mira cómo baja el COP.</b> Al comienzo ambos baldes están a la misma temperatura y el COP es alto. A medida que crece la diferencia entre ellos, la bomba de calor tiene que empujar el calor más «cuesta arriba» y el COP baja. Por eso una bomba de calor funciona mejor con radiadores a baja temperatura.",
             "<b>Se COP falde.</b> Ved start har begge spande samme temperatur, og COP er høj. Efterhånden som forskellen mellem dem vokser, skal varmepumpen skubbe varmen længere »op ad bakke«, og COP falder. Derfor virker en varmepumpe bedst med lave radiatortemperaturer."),
 "ty.try2": ("<b>¿Serpentines pequeños o grandes?</b> Ármala con los serpentines pequeños y luego con los grandes. Los serpentines más grandes necesitan menos diferencia de temperatura para pasar el mismo calor, así que el refrigerante puede condensar a menor temperatura y evaporarse a una mayor: el COP sube.",
             "<b>Små eller store spiraler?</b> Byg den med de små spiraler og derefter med de store. Større spiraler skal bruge en mindre temperaturforskel for at overføre den samme varme, så kølemidlet kan kondensere ved en lavere temperatur og fordampe ved en højere: COP stiger."),
 "ty.try3": ("<b>Un compresor más grande.</b> El compresor grande calienta más rápido pero con un COP menor, y con serpentines pequeños la presión sube hasta que el presostato de seguridad lo detiene.",
             "<b>En større kompressor.</b> Den store kompressor varmer hurtigere, men med lavere COP, og med små spiraler stiger trykket, til sikkerhedspressostaten stopper den."),
 "ty.try4": ("<b>Congela el balde frío.</b> Cuando el agua fría llega a 0 °C se queda ahí mientras se forma hielo: el agua que se congela entrega mucho calor (334 kJ por cada kilogramo), así que la bomba de calor sigue trabajando con calor «gratis» del hielo.",
             "<b>Frys den kolde spand.</b> Når det kolde vand når 0 °C, bliver det der, mens der dannes is: vand, der fryser, afgiver meget varme (334 kJ for hvert kilogram), så varmepumpen bliver ved med at arbejde på »gratis« varme fra isen."),
 "ty.try5": ("<b>Cajas de plumavit.</b> Los baldes abiertos intercambian calor con la habitación, así que el caliente deja de subir y el frío vuelve a calentarse cuando el compresor se detiene. Aíslalos y compara.",
             "<b>Flamingokasser.</b> Åbne spande udveksler varme med rummet, så den varme holder op med at stige, og den kolde bliver varmere igen, når kompressoren stopper. Isolér dem, og sammenlign."),
 "ty.try6": ("<b>Ármala al revés.</b> Intercambia el compresor y la válvula. Ahora se calienta el balde izquierdo. Los aires acondicionados que también calefaccionan hacen exactamente esto, con una válvula de cuatro vías que invierte el flujo.",
             "<b>Byg den omvendt.</b> Byt om på kompressoren og ventilen. Nu bliver den venstre spand varm. Klimaanlæg, der også kan varme, gør præcis det med en firevejsventil, der vender strømmen."),
 "ty.h.real": ("4. Pruébalo de verdad, con seguridad", "4. Prøv det i virkeligheden, sikkert"),
 "ty.real.p": ("Puedes sentir cada parte de la idea de la bomba de calor en casa, sin abrir ninguna máquina.",
               "Du kan mærke hver del af varmepumpens idé derhjemme uden at åbne nogen maskine."),
 "ty.safety": ("<b>Nunca abras un refrigerador, un congelador o un aire acondicionado, ni cortes sus tubos.</b> El refrigerante está a presión, puede ser inflamable (propano e isobutano) y puede causar quemaduras por frío, y solo los técnicos certificados pueden manipularlo. Todos los experimentos de abajo usan aparatos sellados o nada de refrigerante.",
               "<b>Åbn aldrig et køleskab, en fryser eller et klimaanlæg, og skær aldrig i rørene.</b> Kølemidlet er under tryk, kan være brandbart (propan og isobutan) og kan give forfrysninger, og kun certificerede teknikere må håndtere det. Alle forsøgene nedenfor bruger lukkede apparater eller slet intet kølemiddel."),
 "ty.x1h": ("Comprímelo: un bombín de bicicleta", "Pres den sammen: en cykelpumpe"),
 "ty.x1": ("Tapa la salida de un bombín de bicicleta con el dedo y bombea fuerte diez veces. Toca la parte de abajo del bombín: está tibia. Comprimir un gas lo calienta, igual que el compresor calienta el refrigerante.",
           "Hold en finger for udgangen på en cykelpumpe, og pump hårdt ti gange. Mærk på bunden af pumpen: den er varm. Når man presser en gas sammen, bliver den varm, ligesom kompressoren varmer kølemidlet."),
 "ty.x2h": ("Suéltalo: un elástico", "Slip den: en elastik"),
 "ty.x2": ("Estira rápido un elástico grueso y tócalo con el labio: se siente tibio. Mantenlo estirado diez segundos, suéltalo rápido y vuelve a tocarlo: se siente fresco. Al soltarse absorbe calor, como el refrigerante después de la válvula.",
           "Stræk en tyk elastik hurtigt, og hold den mod læben: den føles varm. Hold den strakt i ti sekunder, slip den hurtigt, og mærk igen: den føles kølig. Når den slipper, optager den varme, ligesom kølemidlet efter ventilen."),
 "ty.x3h": ("Tu refrigerador es una bomba de calor", "Dit køleskab er en varmepumpe"),
 "ty.x3": ("Pon un termómetro dentro del refrigerador y otro junto al serpentín de atrás (o de abajo). Adentro hay unos 5 °C y atrás está tibio: el calor se bombea desde los alimentos hacia la cocina. Un medidor de energía para enchufe muestra qué poca electricidad necesita.",
           "Sæt et termometer i køleskabet og et andet ved spiralen bagpå (eller nedenunder). Indeni er der omkring 5 °C, bagpå er det varmt: varmen pumpes ud af maden og ud i køkkenet. En energimåler til stikkontakten viser, hvor lidt strøm det kræver."),
 "ty.x4h": ("Una bomba de calor de estado sólido (con un adulto)", "En varmepumpe uden bevægelige dele (sammen med en voksen)"),
 "ty.x4": ("Un módulo Peltier es una pequeña placa que bombea calor de una cara a la otra cuando pasa electricidad, sin partes móviles. Pon un vaso de agua en cada cara, aliméntalo con 12 V unos minutos y mide ambos vasos: uno se calienta y el otro se enfría. Mantén siempre la cara caliente sobre un disipador o en agua, o se sobrecalienta en segundos.",
           "Et Peltier-element er en lille flise, der pumper varme fra den ene side til den anden, når der løber strøm igennem, uden bevægelige dele. Sæt et glas vand på hver side, kør det på 12 V i nogle minutter, og mål begge glas: det ene bliver varmere, det andet koldere. Hold altid den varme side på en køleplade eller i vand, ellers bliver den overophedet på få sekunder."),
 "ty.h.buy": ("5. Lista de compras: construye el juguete de verdad", "5. Indkøbsliste: byg legetøjet i virkeligheden"),
 "ty.buy.p": ("Hay tres formas de construir una bomba de calor real con dos baldes y medir su COP. Los precios son aproximados, en euros (2026); compara antes de comprar.",
              "Der er tre måder at bygge en rigtig varmepumpe med to spande og måle dens COP. Priserne er cirkapriser i euro (2026); sammenlign, før du køber."),
 "ty.b1h": ("A. Lista para usar: una bomba de calor escolar sellada", "A. Klar til brug: en lukket skolevarmepumpe"),
 "ty.b1p": ("Lo más parecido al juguete. Los proveedores de material educativo venden bombas de calor de demostración con un compresor pequeño, una válvula de expansión, dos serpentines de cobre en recipientes con agua, manómetros y un visor, cargadas con refrigerante y selladas en fábrica. Nunca tocas el refrigerante.",
            "Det, der ligner legetøjet mest. Leverandører af undervisningsmateriel sælger demonstrationsvarmepumper med en lille kompressor, en ekspansionsventil, to kobberspiraler i vandbeholdere, manometre og et skueglas, fyldt med kølemiddel og lukket fra fabrikken. Du rører aldrig kølemidlet."),
 "ty.b1a": ('Bomba de calor de demostración para colegios, sellada y precargada (busca "heat pump demonstrator" o «bomba de calor didáctica» en proveedores de material de física) — unos €900–2.500',
            'Demonstrationsvarmepumpe til skoler, lukket og forfyldt (søg efter "heat pump demonstrator" eller »varmepumpe demonstration« hos leverandører af fysikudstyr) — ca. €900–2.500'),
 "ty.b1b": ("Dos termómetros digitales con sonda — unos €10–25 cada uno", "To digitale termometre med føler — ca. €10–25 stykket"),
 "ty.b1c": ("Un medidor de energía para enchufe, para leer la electricidad usada — unos €15–30", "En energimåler til stikkontakten, så du kan aflæse strømforbruget — ca. €15–30"),
 "ty.b1d": ("Un jarro medidor y un cronómetro (sirve un teléfono)", "Et litermål og et stopur (en telefon kan bruges)"),
 "ty.b1n": ("Lo mejor para un colegio: pregunta en el departamento de física, muchos ya tienen una.", "Bedst til en skole: spørg fysiklærerne, mange skoler har allerede en."),
 "ty.b2h": ("B. El juguete con piezas sueltas (el trabajo con refrigerante lo hace un técnico)", "B. Legetøjet af løse dele (kølemiddelarbejdet laves af en tekniker)"),
 "ty.b2p": ("Exactamente las piezas del juguete. Puedes comprarlas y ordenarlas, pero unir los tubos, probar fugas, hacer vacío y cargar el refrigerante lo debe hacer un técnico frigorista certificado: lo exige la ley, y el gas está a alta presión y puede ser inflamable.",
            "Præcis delene i legetøjet. Du kan købe dem og stille dem op, men samling af rørene, tæthedsprøve, vakuum og påfyldning af kølemiddel skal laves af en certificeret kølemontør: loven kræver det, og gassen er under højt tryk og kan være brandbar."),
 "ty.b2a": ("<b>Compresor:</b> un compresor hermético pequeño de refrigerador, de unos 1/8 hp (80–100 W), para R290 o R134a — unos €60–150",
            "<b>Kompressor:</b> en lille hermetisk køleskabskompressor, ca. 1/8 hk (80–100 W), til R290 eller R134a — ca. €60–150"),
 "ty.b2b": ('<b>Dos serpentines:</b> tubo de cobre blando para refrigeración, de 6 mm (1/4"), unos 3 m por serpentín, enrollado alrededor de una botella — unos €25–40',
            '<b>To spiraler:</b> blødt kobberkølerør, 6 mm (1/4"), ca. 3 m til hver spiral, viklet om en flaske — ca. €25–40'),
 "ty.b2c": ("<b>Válvula de expansión:</b> un tubo capilar adecuado al compresor (o una pequeña válvula de expansión termostática) — unos €5–60",
            "<b>Ekspansionsventil:</b> et kapillarrør, der passer til kompressoren (eller en lille termostatisk ekspansionsventil) — ca. €5–60"),
 "ty.b2d": ("<b>Filtro deshidratador</b>, que mantiene la humedad fuera del circuito — unos €5–15", "<b>Tørrefilter</b>, der holder fugt ude af kredsen — ca. €5–15"),
 "ty.b2e": ("<b>Visor de líquido</b>, para ver el refrigerante burbujear y volverse líquido — unos €10–20", "<b>Skueglas</b>, så du kan se kølemidlet boble og blive flydende — ca. €10–20"),
 "ty.b2f": ("<b>Dos manómetros</b> (lado de alta y de baja) con válvulas de servicio — unos €30–60", "<b>To manometre</b> (høj- og lavtryksside) med serviceventiler — ca. €30–60"),
 "ty.b2g": ("<b>Presostato de seguridad de alta</b>, el mismo trabajo que en el juguete — unos €15–30", "<b>Højtrykspressostat</b>, samme job som i legetøjet — ca. €15–30"),
 "ty.b2j": ("Una tabla de madera para montarlo, dos baldes de 5 L o cajas de plumavit, dos termómetros y un medidor de energía",
            "En træplade at montere det på, to 5 L spande eller flamingokasser, to termometre og en energimåler"),
 "ty.b2i": ("<b>El trabajo del técnico:</b> soldadura fuerte, prueba de presión con nitrógeno, vacío y carga (unos cientos de gramos de refrigerante) — pide un presupuesto",
            "<b>Teknikerens arbejde:</b> hårdlodning, trykprøve med kvælstof, vakuum og påfyldning (et par hundrede gram kølemiddel) — bed om et tilbud"),
 "ty.b3h": ("C. Constrúyela tú: una bomba de calor Peltier (con un adulto)", "C. Byg den selv: en Peltier-varmepumpe (sammen med en voksen)"),
 "ty.b3p": ("Sin refrigerante y sin compresor: un módulo Peltier bombea calor con electricidad. Es menos eficiente que un compresor, pero prueba la misma idea con dos baldes, y la puedes armar en la mesa de la cocina en una tarde.",
            "Intet kølemiddel og ingen kompressor: et Peltier-element pumper varme elektrisk. Det er mindre effektivt end en kompressor, men det afprøver den samme idé med to spande, og du kan bygge det på køkkenbordet på en eftermiddag."),
 "ty.b3a": ("<b>Módulo Peltier</b> TEC1-12706 (12 V, unos 6 A); compra dos por si uno se daña — unos €5–10 cada uno",
            "<b>Peltier-element</b> TEC1-12706 (12 V, ca. 6 A); køb to, hvis det ene går i stykker — ca. €5–10 stykket"),
 "ty.b3b": ("<b>Dos bloques de agua de aluminio</b>, de 40 × 40 mm (se venden para refrigeración líquida de PC) — unos €5–10 cada uno",
            "<b>To vandblokke i aluminium</b>, 40 × 40 mm (sælges til vandkøling af pc'er) — ca. €5–10 stykket"),
 "ty.b3c": ("<b>Dos bombas sumergibles pequeñas de 12 V</b> y 2 m de manguera de silicona que les calce — unos €10–20",
            "<b>To små 12 V dykpumper</b> og 2 m silikoneslange, der passer til dem — ca. €10–20"),
 "ty.b3d": ("<b>Fuente de poder de 12 V</b>, de al menos 10 A, con bornes de tornillo — unos €20–30", "<b>12 V strømforsyning</b> på mindst 10 A med skrueterminaler — ca. €20–30"),
 "ty.b3e": ("<b>Pasta térmica</b> y dos prensas pequeñas o pernos para apretar el sándwich — unos €5–10", "<b>Kølepasta</b> og to små tvinger eller bolte til at presse sandwichen sammen — ca. €5–10"),
 "ty.b3f": ("<b>Medidor de potencia DC</b> (volts, amperes, watts) entre la fuente y el módulo — unos €10–20", "<b>DC-effektmåler</b> (volt, ampere, watt) mellem forsyningen og elementet — ca. €10–20"),
 "ty.b3g": ("Dos recipientes aislados (cajas de plumavit o termos de comida de 2 L), dos termómetros, un jarro medidor",
            "To isolerede beholdere (flamingokasser eller 2 L madtermoer), to termometre, et litermål"),
 "ty.b3s": ("<b>Cómo armarla:</b> pon pasta en un bloque de agua en cada cara del módulo Peltier y apriétalos. Pon una bomba en cada recipiente y haz pasar su agua por un bloque y de vuelta. Llena ambos recipientes con la misma cantidad de agua a la misma temperatura, enciende las bombas y luego el módulo. Un recipiente se calienta y el otro se enfría.",
            "<b>Sådan samler du den:</b> sæt en vandblok med kølepasta på hver side af Peltier-elementet, og spænd dem sammen. Sæt en pumpe i hver beholder, og lad dens vand løbe gennem den ene blok og tilbage. Fyld begge beholdere med lige meget vand ved samme temperatur, tænd pumperne og derefter elementet. Den ene beholder bliver varmere, den anden koldere."),
 "ty.b3n": ("Nunca hagas funcionar el módulo sin agua circulando por su cara caliente: se quema en segundos. Mantén la electricidad lejos del agua y sécate las manos.",
            "Kør aldrig elementet uden vand, der løber på den varme side: det brænder af på få sekunder. Hold det elektriske væk fra vandet, og tør hænderne."),
 "ty.h.measure": ("Mide tu COP", "Mål din COP"),
 "ty.m1": ("Anota la masa del agua (1 litro es 1 kg), ambas temperaturas cada 5 minutos y la electricidad. Luego:",
           "Skriv vandets masse ned (1 liter er 1 kg), begge temperaturer hvert 5. minut og strømforbruget. Derefter:"),
 "ty.m2": ("calor hacia el balde caliente (kJ) = masa (kg) × 4,19 × aumento de temperatura (°C)<br>electricidad (kJ) = watts × segundos ÷ 1000 &nbsp; (o kWh × 3600)<br>COP = calor hacia el balde caliente ÷ electricidad",
           "varme ind i den varme spand (kJ) = masse (kg) × 4,19 × temperaturstigning (°C)<br>strøm (kJ) = watt × sekunder ÷ 1000 &nbsp; (eller kWh × 3600)<br>COP = varme ind i den varme spand ÷ strøm"),
 "ty.m3": ("Ejemplo: 5 kg de agua que se calientan 10 °C absorben 5 × 4,19 × 10 = 210 kJ. Si el medidor marca 80 W durante 20 minutos, son 80 × 1200 ÷ 1000 = 96 kJ, así que COP = 210 ÷ 96 = 2,2. Mide en la primera media hora, antes de que los baldes intercambien mucho calor con la habitación, y compara con el juguete de arriba. Un módulo Peltier dará un COP de calefacción de 1,2–2; un compresor, de 2–4.",
           "Eksempel: 5 kg vand, der bliver 10 °C varmere, optager 5 × 4,19 × 10 = 210 kJ. Viser måleren 80 W i 20 minutter, er det 80 × 1200 ÷ 1000 = 96 kJ, så COP = 210 ÷ 96 = 2,2. Mål i den første halve time, før spandene udveksler meget varme med rummet, og sammenlign med legetøjet ovenfor. Et Peltier-element giver en varme-COP på ca. 1,2–2; en kompressor ca. 2–4."),
 "ty.real.note": ("El juguete de arriba está idealizado: la potencia del compresor es fija, los serpentines tienen un tamaño fijo y se ignoran las pérdidas de presión. Su ciclo de refrigerante se calcula con las mismas tablas de propiedades de CoolProp que el diseñador completo.",
                  "Legetøjet ovenfor er idealiseret: kompressorens effekt er fast, spiralerne har en fast størrelse, og tryktab er udeladt. Kølekredsen beregnes med de samme CoolProp-tabeller som i den fulde designer."),
}
